        uint256 amount = 100 ether;
        uint256 initialRate = token.reflectionFromToken(1 ether, false) / 1 ether;

        // Owner mints new tokens
        vm.prank(owner);
        token.mint(owner, amount);

        // Get actual reflection increase for minted tokens
        uint256 mintedReflection = token.reflectionFromToken(amount, false);
        // Expected reflection increase based on initial rate
        uint256 expectedReflection = amount * initialRate;

        // Verify reflection accounting error - actual is much less than expected
        assertLt(mintedReflection, expectedReflection);
    }
}
